$(document).ready(function () {

    // Header
    if (window.innerWidth >= 993) {
        $('.header__item').hover(function () {
            $(this).toggleClass('header__item--active')
        })
    }

    $('.burger').click(function () {
        $('.menu').addClass('menu--active')
        $('.menu-bg').addClass('menu-bg--active')
        $('body').addClass('fixed-body')
    })

    $('.menu__close').click(function () {
        $('.menu').removeClass('menu--active')
        $('.menu-bg').removeClass('menu-bg--active')
        $('body').removeClass('fixed-body')
    })

    // Accordion
    $(".item-show").click((function(){
        $(this).toggleClass("item-show--active"),
        $(this).siblings(".item-hidden").slideToggle()
    }));

})